    bit_reabrir_pie: "Deshace el cierre para que se pueda volver a trabajar o volver a cerrar. Si lo cerró el equipo desde la calle, su marca de fin se anula: no se borra, queda con tu nombre y el motivo.",
    bit_reabrir_ph: "Por qué se reabre",
