    bit_reabrir_seguro: "¿Reabrir este día? Si lo cerró el equipo, su marca de fin se anula.",
    bit_reabrir_boton: "Reabrir el día",
    ay_bit_reabrir_para: "Deshacer el cierre de un día que se cerró por error, o que se cerró antes de tiempo porque el equipo siguió trabajando.",
    ay_bit_reabrir_cuando: "Cuando el día se queda cerrado mal: entra a nómina con horas que no son, o el equipo no puede volver a marcar su fin.",
    bit_manana_titulo: "Mañana arrancamos a las…",
    bit_manana_pie: "Cambia la hora del siguiente día de este equipo ({fecha}) y le avisa a quien ya había confirmado.",
