    /* La pantalla de Odoo (seccion 64). */
    odo_sub: "Lo que Centauro lee de Odoo: el personal de seguridad y la flota. La primera lectura de cada una se hace aquí, después de ver el ensayo; de ahí en adelante se lee sola cada hora. Nada de esto escribe en Odoo.",
