    odo_t_personal: "Personal",
    odo_t_flota: "Flota",
    odo_a_mano: "a mano",
    odo_sola_h: "sola, cada hora",
    ay_odo_personal_para: "Trae de Odoo al personal de seguridad —puesto «Personal de Seguridad» o «Security Driver»— con su plaza, celular, correo personal, referencia y foto. Da de alta a quien falta, con su acceso a la app; le cambia a cada quien lo que cambió en Odoo, y da de baja a quien archivaron allá.",
    ay_odo_personal_cuando: "Aquí mismo: si la llave de Odoo vence —dura tres meses como máximo— el ensayo lo dice, y la de cada hora deja de aparecer en «Las últimas lecturas». Y quien no entra por algo de Odoo sale en Pendientes, con lo que le falta y su No. Odoo.",
    ay_odo_personal_numero: "Todo sale de leer Odoo en ese momento. Altas: personas de seguridad que Centauro no tiene. Cambios: las que ya tiene y en Odoo dicen otra cosa. Bajas: las que Centauro lleva y en Odoo ya no están activas.",
    ay_odo_flota_para: "Trae de Odoo las unidades con la etiqueta «PROTECCIÓN EJECUTIVA» o «pe», con su placa, categoría y plaza, y los días que cada una pasa en el taller, para dejar de ofrecerla esos días. Con la placa se liga cada unidad a su GPS.",
    ay_odo_flota_cuando: "Aquí mismo: si la llave vence, el ensayo lo dice y la de cada hora deja de aparecer abajo. Una unidad sin placa, o con una categoría o una plaza que Centauro no tiene, sale en Pendientes con su No. Odoo hasta que se corrija allá.",
    ay_odo_flota_numero: "Todo sale de leer Odoo en ese momento. Altas: unidades de Protección Ejecutiva que Centauro no tiene. Bajas: las que Centauro lleva y en Odoo se archivaron o ya no son de Protección Ejecutiva.",
    ay_odo_pendientes_para: "Lo que no entra a Centauro hasta que se corrija en Odoo, agrupado por lo que falta y con el No. Odoo de cada uno para encontrarlo allá. Es la lista de trabajo de RH, o de quien lleva la flota en Odoo.",
    ay_odo_pendientes_cuando: "En cada ensayo y en cada lectura de cada hora. Lo pendiente no se toca ni se borra: se queda afuera. En cuanto se corrige en Odoo, la siguiente lectura lo toma sola; aquí no se captura nada.",
    ay_odo_pendientes_numero: "El total cuenta a cada quien una vez, aunque le falten dos cosas; en la lista sale en cada grupo de lo que le falta. En la flota también cuentan las entradas del taller con fechas que no cuadran.",
    ay_odo_historial_para: "Cada vez que Centauro leyó Odoo —a mano desde aquí o sola cada hora—, quién la hizo y qué resultó: altas, cambios, bajas y pendientes.",
    ay_odo_historial_cuando: "Si la de cada hora deja de aparecer, algo la detuvo. Casi siempre es la llave de Odoo, que vence a los tres meses como máximo: hay que crear otra en Odoo y que TI la ponga en el servidor.",
    ay_odo_historial_numero: "Son las cuentas que dejó cada lectura al guardarse. Las de cada hora sin novedades también dejan su renglón, para que se vea que corrieron.",
    /* --- seccion 74: el personal de oficina desde Odoo */
    odo_oficina: "El personal de oficina",
    odo_t_oficina: "Oficina",
    odo_leidos_oficina: "Personal de oficina en Odoo: {n} · sin cambio: {s}",
    odo_altas_oficina_pie: "llegan listos para su acceso; RH se lo da en Accesos",
    odo_bajas_oficina_pie: "se les cierra el acceso",
    odo_confirmar_oficina: "Llegan: {altas}, sin acceso todavía: RH se los da en Accesos, con su puesto sugerido. Se ponen al día: {cambios} (vinculadas por primera vez: {vinculadas}). Bajas: {bajas}, y se les cierra el acceso. Lo pendiente no se toca. Al aplicar se vuelve a leer Odoo: si alguien lo movió desde el ensayo, se guarda lo de ese momento.",
    odo_sin_correo_trabajo: "Sin correo de trabajo",
    odo_sin_correo_trabajo_pie: "RH se lo pone en Odoo",
    odo_l_sin_correo: "Sin correo de trabajo en Odoo",
    odo_l_sin_sugerencia: "Sin puesto sugerido",
    odo_sin_sugerencia_pie: "Su puesto de Odoo no se parece a ninguno de Centauro. RH lo escoge a mano al darle acceso, o agrega ese puesto de Odoo al puesto que le toca, en Accesos → Puestos.",
    odo_sin_lugar: "{n} sin un lugar de trabajo en Odoo que Centauro conozca: quedan en Ciudad de México hasta que Odoo diga uno.",
    odo_f_trabajo_mal: "Correo de trabajo mal escrito",
    odo_f_trabajo_dedo: "Correo de trabajo con error de dedo",
    odo_f_trabajo_repetido: "Correo de trabajo repetido en Odoo",
    odo_f_era_seguridad: "En Centauro es personal de seguridad; en Odoo ya no",
    odo_f_correo_de_seguridad: "Su correo es de alguien del personal de seguridad en Centauro",
    odo_f_ahora_seguridad: "Ahora es personal de seguridad en Odoo",
    odo_q_puesto: "puesto",
    odo_q_area: "área",
    odo_b_no_tenia: "no tenía acceso",
    ay_odo_oficina_para: "Trae de Odoo al personal de oficina —todo empleado activo que no es personal de seguridad— con su correo de trabajo, su puesto y su departamento. No les da acceso: los deja listos en Accesos, con el puesto de Centauro que sugiere su puesto de Odoo, para que Recursos Humanos se lo dé con un clic. Si Odoo archiva a alguien, su acceso se cierra.",
    ay_odo_oficina_cuando: "Aquí mismo: la primera vez se aplica a mano, después de ver el ensayo, y de ahí en adelante se lee sola cada hora. Quien no tiene correo de trabajo en Odoo sale aparte: RH se lo pone allá y llega solo en la siguiente lectura.",
    ay_odo_oficina_numero: "Todo sale de leer Odoo en ese momento. Llegan: gente de oficina con correo de trabajo que Centauro no tiene. Cambios: quien ya estaba y en Odoo dice otra cosa, o se reconoce por primera vez por su correo. Bajas: quien Centauro lleva y en Odoo se archivó.",
    ofi_tab_con: "Con acceso ({n})",
    ofi_tab_oficina: "Oficina, sin acceso ({n})",
    ofi_tab_sin_correo: "Sin correo en Odoo ({n})",
    ofi_pie: "Vienen de Odoo: empleados activos que no son personal de seguridad. El puesto sugerido sale de su puesto en Odoo; se puede cambiar antes de dar el acceso.",
    ofi_sin_lectura: "Todavía no se lee la oficina de Odoo: la primera vez se hace en la pantalla de Odoo, después de ver su ensayo.",
    ofi_nadie: "Toda la oficina que llegó de Odoo ya tiene acceso.",
    ofi_sin_correo_pie: "No tienen correo de trabajo en Odoo, así que no pueden entrar. Recursos Humanos se lo pone en Odoo y llegan solos en la siguiente lectura.",
    ofi_segun_lectura: "Según la lectura del {cuando}.",
    ofi_todos_con_correo: "Todos tienen su correo de trabajo en Odoo.",
    ofi_sin_sugerido: "Sin puesto sugerido",
    ofi_sin_sugerido_pie: "Su puesto de Odoo no se parece a ninguno: se escoge a mano.",
    ofi_dar: "Dar acceso",
    /* --- seccion 75: los clientes desde Odoo */
    odo_clientes: "Los clientes",
    cli_sin_tarifario: "(sin tarifario)",
    odo_sin_tarifario_titulo: "Clientes sin tarifario ({n})",
    odo_sin_tarifario_pie: "Llegaron de Odoo sin tarifario: hasta que se les ponga no se les puede cotizar. Muchos comparten el mismo, así que se puede poner a todos los de un país de una vez.",
