    ay_odo_ta_pendientes_para: "Lo que la lectura no pudo leer o no quiso adivinar, agrupado por lo que falta: productos sin confirmar, dos precios para lo mismo, listas sin país o sin cliente. Lo demás se lee igual.",
    ay_odo_ta_pendientes_cuando: "Los productos se confirman en Facturación → Tarifarios; lo demás se acomoda en Odoo, en Ventas → Configuración → Listas de precios. La siguiente lectura lo toma sola.",
