    ay_hd_para: "See at a glance how much overtime the day had and where it comes from: the schedule, when the hours start running and when it ended.",
    ay_hd_cuando: "The hours of the day run from the report time, or from the meet and greet if it was earlier. Past that limit, every hour or fraction is an overtime hour: one extra minute already counts. Only full days have overtime; the client is billed at the role's overtime price, and it is paid to whoever stayed until the end.",
    ay_hd_corregir_para: "Correct the time the team started with the executive or the time it ended, when the check-in was wrong.",
    ay_hd_corregir_cuando: "When the team checked out late —on reaching the base— or forgot, and the client confirms a different time. The original time is kept with your name and the reason, and finance sees it at sign-off. The consultant corrects until their sign-off; after that, hours are corrected with finance.",
