    fac_tab_tarifarios: "Price lists",
    tar_titulo_productos: "What each Odoo product is",
    tar_productos_pie: "Each Odoo product says what it is in Centauro. Centauro suggests it from the name and finance confirms it once. With this the list prices are read and, in step 4, the invoice goes out with the same products.",
    tar_confirmar_sugeridos: "Confirm the suggested ones ({n})",
