    tar_nota_centauro: "Price list entered in Centauro: it doesn't come from Odoo.",
    tar_nota_retenido: "It doesn't take its Odoo list yet: it keeps this one until its list has prices Centauro can read.",
    tar_leyenda: "In black, what the list agrees; in gray, what it takes from the general list, another list or the product's «Sales price». Where it says «no price», that can't be quoted.",
    tar_sin_tarifario: "This client doesn't have a price list yet: it can't be quoted.",
    tar_sin_tarifario_odoo: "This client doesn't have a price list yet: it takes it from its Odoo list at the next price-list reading.",
    tar_sin_tarifario_corto: "no price list",
