    bit_reabrir_titulo: "Reabrir o dia",
    bit_reabrir_pie: "Desfaz o fechamento para que o dia possa ser trabalhado ou fechado de novo. Se a equipe fechou da rua, a marca de fim é anulada: não se apaga, fica com o seu nome e o motivo.",
    bit_reabrir_ph: "Por que se reabre",
    bit_reabrir_falta: "Escreva por que se reabre.",
    bit_reabrir_seguro: "Reabrir este dia? Se a equipe fechou, a marca de fim é anulada.",
    bit_reabrir_boton: "Reabrir o dia",
    ay_bit_reabrir_para: "Desfazer o fechamento de um dia fechado por engano, ou fechado antes da hora porque a equipe continuou trabalhando.",
    ay_bit_reabrir_cuando: "Quando o dia fica mal fechado: entra na folha com horas erradas, ou a equipe não pode marcar o fim de novo.",
    bit_manana_titulo: "Amanhã começamos às…",
    bit_manana_pie: "Muda a hora do próximo dia desta equipe ({fecha}) e avisa quem já havia confirmado.",
