    ay_bit_manana_para: "Deixar fixada a hora em que começa o dia seguinte desta equipe, no momento em que o principal a diz.",
    ay_bit_manana_cuando: "Ao fechar o dia, quando o executivo diz a que horas se veem amanhã. Muda a hora do dia seguinte DESTA equipe — se o serviço tem outra equipe em outra cidade, essa não se toca — e avisa quem já havia confirmado sobre a hora anterior: uma confirmação feita sobre uma hora que mudou aponta para algo que já não é verdade.",
    sc_arranco_tarde: "Este dia começou às {h}, depois da hora em que devia terminar. A hora proposta são as suas horas contratadas desde que de fato começou; mude-a se souber a real.",
