    ay_hd_para: "Ver num relance quantas horas extras o dia teve e de onde saem: o programado, desde quando correm as horas e a que horas terminou.",
    ay_hd_cuando: "As horas do dia correm desde a hora de apresentação, ou desde o meet and greet se foi antes. Passado esse limite, cada hora ou fração é uma hora extra: um minuto a mais já conta. Só o dia completo tem horas extras; são cobradas do cliente pelo preço de hora extra da função e pagas a quem ficou até o fim.",
