    prof_manejo: "Direção",
    cmp_unidad_gps: "Tem GPS. Durante o seu serviço —do caminho ao ponto até a sua marcação de fim— ele confirma as suas marcações e conta os quilômetros. Fora do serviço ninguém olha onde ela está; só vale o botão de pânico.",
