    /* La pantalla de Odoo (seccion 64). */
    odo_sub: "O que o Centauro lê do Odoo: o pessoal de segurança e a frota. A primeira leitura de cada um se faz aqui, depois de ver o ensaio; daí em diante é lida sozinha a cada hora. Nada disto escreve no Odoo.",
