    odo_t_personal: "Pessoal",
    odo_t_flota: "Frota",
    odo_a_mano: "à mão",
    odo_sola_h: "sozinha, a cada hora",
    ay_odo_personal_para: "Traz do Odoo o pessoal de segurança —cargo «Personal de Seguridad» ou «Security Driver»— com praça, celular, e-mail pessoal, referência e foto. Cadastra quem falta, com o seu acesso ao app; muda em cada pessoa o que mudou no Odoo; e desliga quem foi arquivado lá.",
    ay_odo_personal_cuando: "Aqui mesmo: se a chave do Odoo vencer —dura três meses no máximo— o ensaio avisa, e a de cada hora deixa de aparecer em «As últimas leituras». E quem não entra por algo do Odoo aparece em Pendentes, com o que falta e o seu Nº Odoo.",
    ay_odo_personal_numero: "Tudo sai de ler o Odoo naquele momento. Entradas: pessoas de segurança que o Centauro não tem. Mudanças: as que ele tem e no Odoo dizem outra coisa. Saídas: as que o Centauro tem e no Odoo já não estão ativas.",
    ay_odo_flota_para: "Traz do Odoo as unidades com a etiqueta «PROTECCIÓN EJECUTIVA» ou «pe», com placa, categoria e praça, e os dias que cada uma passa na oficina, para não oferecê-la nesses dias. É pela placa que cada unidade se liga ao seu GPS.",
    ay_odo_flota_cuando: "Aqui mesmo: se a chave vencer, o ensaio avisa e a de cada hora deixa de aparecer abaixo. Uma unidade sem placa, ou com uma categoria ou praça que o Centauro não tem, aparece em Pendentes com o seu Nº Odoo até ser corrigida lá.",
    ay_odo_flota_numero: "Tudo sai de ler o Odoo naquele momento. Entradas: unidades de Proteção Executiva que o Centauro não tem. Saídas: as que o Centauro tem e no Odoo foram arquivadas ou já não são de Proteção Executiva.",
    ay_odo_pendientes_para: "O que não entra no Centauro até ser corrigido no Odoo, agrupado pelo que falta e com o Nº Odoo de cada um para encontrá-lo lá. É a lista de trabalho do RH, ou de quem cuida da frota no Odoo.",
    ay_odo_pendientes_cuando: "Em cada ensaio e em cada leitura de cada hora. O pendente não é tocado nem apagado: fica de fora. Assim que é corrigido no Odoo, a leitura seguinte o pega sozinha; aqui não se cadastra nada.",
    ay_odo_pendientes_numero: "O total conta cada um uma vez, mesmo que faltem duas coisas; na lista aparece em cada grupo do que falta. Na frota também contam as entradas da oficina com datas que não batem.",
    ay_odo_historial_para: "Cada vez que o Centauro leu o Odoo —à mão daqui ou sozinho a cada hora—, quem fez e o que resultou: entradas, mudanças, saídas e pendentes.",
    ay_odo_historial_cuando: "Se a de cada hora deixar de aparecer, algo a parou. Quase sempre é a chave do Odoo, que vence em três meses no máximo: é preciso criar outra no Odoo e a TI colocá-la no servidor.",
    ay_odo_historial_numero: "São as contas que cada leitura deixou ao ser salva. As de cada hora sem novidades também deixam a sua linha, para que se veja que rodaram.",
    /* --- seccion 74: el personal de oficina desde Odoo */
    odo_oficina: "O pessoal de escritório",
    odo_t_oficina: "Escritório",
    odo_leidos_oficina: "Pessoal de escritório no Odoo: {n} · sem mudança: {s}",
    odo_altas_oficina_pie: "chegam prontos para o acesso; o RH o dá em Acessos",
    odo_bajas_oficina_pie: "o acesso delas é fechado",
    odo_confirmar_oficina: "Chegam: {altas}, ainda sem acesso: o RH o dá em Acessos, com o cargo sugerido. Atualizadas: {cambios} (vinculadas pela primeira vez: {vinculadas}). Saídas: {bajas}, e o acesso delas é fechado. O pendente não é tocado. Ao aplicar, o Odoo é lido de novo: se alguém mexeu nele desde o ensaio, salva-se o que houver naquele momento.",
    odo_sin_correo_trabajo: "Sem e-mail de trabalho",
    odo_sin_correo_trabajo_pie: "o RH o coloca no Odoo",
    odo_l_sin_correo: "Sem e-mail de trabalho no Odoo",
    odo_l_sin_sugerencia: "Sem cargo sugerido",
    odo_sin_sugerencia_pie: "O cargo no Odoo não se parece com nenhum do Centauro. O RH o escolhe à mão ao dar o acesso, ou acrescenta esse cargo do Odoo ao cargo certo, em Acessos → Cargos.",
    odo_sin_lugar: "{n} sem um local de trabalho no Odoo que o Centauro conheça: ficam na Cidade do México até o Odoo dizer um.",
    odo_f_trabajo_mal: "E-mail de trabalho mal escrito",
    odo_f_trabajo_dedo: "E-mail de trabalho com erro de digitação",
    odo_f_trabajo_repetido: "E-mail de trabalho repetido no Odoo",
    odo_f_era_seguridad: "No Centauro é pessoal de segurança; no Odoo já não",
    odo_f_correo_de_seguridad: "O e-mail é de alguém do pessoal de segurança no Centauro",
    odo_f_ahora_seguridad: "Agora é pessoal de segurança no Odoo",
    odo_q_puesto: "cargo",
    odo_q_area: "área",
    odo_b_no_tenia: "não tinha acesso",
    ay_odo_oficina_para: "Traz do Odoo o pessoal de escritório —todo empregado ativo que não é pessoal de segurança— com o e-mail de trabalho, o cargo e o departamento. Não dá acesso: deixa cada um pronto em Acessos, com o cargo do Centauro sugerido pelo cargo do Odoo, para o RH dar com um clique. Se o Odoo arquiva alguém, o acesso é fechado.",
    ay_odo_oficina_cuando: "Aqui mesmo: da primeira vez aplica-se à mão, depois de ver o ensaio, e daí em diante é lido sozinho a cada hora. Quem não tem e-mail de trabalho no Odoo aparece à parte: o RH o coloca lá e a pessoa chega sozinha na leitura seguinte.",
    ay_odo_oficina_numero: "Tudo sai de ler o Odoo naquele momento. Chegam: pessoas de escritório com e-mail de trabalho que o Centauro não tem. Mudanças: quem já estava e no Odoo diz outra coisa, ou é reconhecido pela primeira vez pelo e-mail. Saídas: quem o Centauro tem e no Odoo foi arquivado.",
    ofi_tab_con: "Com acesso ({n})",
    ofi_tab_oficina: "Escritório, sem acesso ({n})",
    ofi_tab_sin_correo: "Sem e-mail no Odoo ({n})",
    ofi_pie: "Vêm do Odoo: empregados ativos que não são pessoal de segurança. O cargo sugerido sai do cargo no Odoo; pode ser mudado antes de dar o acesso.",
    ofi_sin_lectura: "O escritório ainda não foi lido do Odoo: da primeira vez faz-se na tela do Odoo, depois de ver o ensaio.",
    ofi_nadie: "Todo o escritório que veio do Odoo já tem acesso.",
    ofi_sin_correo_pie: "Não têm e-mail de trabalho no Odoo, então não podem entrar. O RH o coloca no Odoo e chegam sozinhos na leitura seguinte.",
    ofi_segun_lectura: "Segundo a leitura de {cuando}.",
